/* Draws BASE_MAP with Leaflet. No tiles, no network — the geometry above is the
   whole basemap, so it works from disk and offline.

   var base = createBaseMap(map, {theme: 'dark', lang: 'en'});
   base.addTo(map);            // it is a normal LayerGroup
   base.setLang('ar');         // place labels switch language
*/
var BASE_MAP_THEMES = {
    light: {
        land: '#f4f1ea', landEdge: '#cfc8b8', water: '#a9c9e6',
        major: '#e0873f', main: '#e3b25a', minor: '#c3bcae',
        label: '#3f3f3f', halo: '#ffffff'
    },
    dark: {
        land: '#16222f', landEdge: '#31465e', water: '#12314a',
        major: '#b9713c', main: '#9c8244', minor: '#465469',
        label: '#c9d6e3', halo: '#0a121c'
    }
};

// Smaller places only earn a label once you are zoomed in enough to place them.
var BASE_MAP_PLACE_ZOOM = { city: 10, town: 11, village: 12, suburb: 13, neighbourhood: 14 };
var BASE_MAP_PLACE_SIZE = { city: 14, town: 12, village: 11, suburb: 11, neighbourhood: 10 };
var BASE_MAP_PLACE_RANK = { city: 0, town: 1, village: 2, suburb: 3, neighbourhood: 4 };

function createBaseMap(map, options) {
    options = options || {};
    var colors = BASE_MAP_THEMES[options.theme === 'dark' ? 'dark' : 'light'];
    var lang = options.lang === 'ar' ? 'ar' : 'en';
    var paneName = options.pane || 'vectorBasePane';

    if (!map.getPane(paneName)) {
        map.createPane(paneName);
        map.getPane(paneName).style.zIndex = options.zIndex || 220;
    }

    var renderer = L.canvas({ pane: paneName });
    var group = L.layerGroup();
    var labels = [];

    L.polygon(BASE_MAP.land, {
        pane: paneName, renderer: renderer, interactive: false,
        color: colors.landEdge, weight: 1, fillColor: colors.land, fillOpacity: 1
    }).addTo(group);

    BASE_MAP.water.forEach(function (ring) {
        L.polygon(ring, {
            pane: paneName, renderer: renderer, interactive: false,
            stroke: false, fillColor: colors.water, fillOpacity: 1
        }).addTo(group);
    });

    [['minor', 1.2], ['main', 2], ['major', 3]].forEach(function (spec) {
        var cls = spec[0];
        BASE_MAP.roads[cls].forEach(function (segment) {
            L.polyline(segment, {
                pane: paneName, renderer: renderer, interactive: false,
                color: colors[cls], weight: spec[1], opacity: 0.95, lineJoin: 'round'
            }).addTo(group);
        });
    });

    function labelHtml(place) {
        var size = BASE_MAP_PLACE_SIZE[place.t] || 11;
        return '<span style="font:600 ' + size + 'px/1 -apple-system,BlinkMacSystemFont,' +
            '\'Segoe UI\',Roboto,sans-serif;color:' + colors.label + ';white-space:nowrap;' +
            'text-shadow:0 0 3px ' + colors.halo + ',0 0 3px ' + colors.halo +
            ',0 0 2px ' + colors.halo + '">' + place.n[lang] + '</span>';
    }

    BASE_MAP.places.forEach(function (place) {
        var marker = L.marker(place.c, {
            pane: paneName, interactive: false, keyboard: false,
            icon: L.divIcon({ className: '', html: labelHtml(place), iconSize: [120, 16] })
        });
        labels.push({ marker: marker, place: place });
    });

    // Labels are placed biggest-place-first; anything that would collide is dropped.
    function refreshLabels() {
        var zoom = map.getZoom();
        var placed = [];

        labels.forEach(function (entry) {
            var wanted = zoom >= (BASE_MAP_PLACE_ZOOM[entry.place.t] || 13);

            if (wanted) {
                var point = map.latLngToContainerPoint(entry.marker.getLatLng());
                for (var i = 0; i < placed.length; i++) {
                    if (Math.abs(point.x - placed[i].x) < 78 && Math.abs(point.y - placed[i].y) < 16) {
                        wanted = false;
                        break;
                    }
                }
                if (wanted) {
                    placed.push(point);
                }
            }

            if (wanted && !group.hasLayer(entry.marker)) {
                group.addLayer(entry.marker);
            } else if (!wanted && group.hasLayer(entry.marker)) {
                group.removeLayer(entry.marker);
            }
        });
    }

    group.setLang = function (next) {
        lang = next === 'ar' ? 'ar' : 'en';
        labels.forEach(function (entry) {
            entry.marker.setIcon(L.divIcon({
                className: '', html: labelHtml(entry.place), iconSize: [120, 16]
            }));
        });
    };

    labels.sort(function (a, b) {
        return (BASE_MAP_PLACE_RANK[a.place.t] || 9) - (BASE_MAP_PLACE_RANK[b.place.t] || 9);
    });

    group.on('add', function () {
        refreshLabels();
        map.on('zoomend moveend', refreshLabels);
    });

    group.on('remove', function () {
        map.off('zoomend moveend', refreshLabels);
    });

    group.getAttribution = function () {
        return BASE_MAP.attribution;
    };

    return group;
}
